const toRad = d => d * Math.PI / 180;

// Current device location (San Francisco, CA)
const lat1 = 37.7749, lon1 = -122.4194;

// Shipping address: Boston, MA 02118 (approximate coords)
const lat2 = 42.3396, lon2 = -71.0693;

// Haversine formula
const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 +
          Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));

const R_km = 6371.0;
const R_mi = 3958.8;

console.log('From:  San Francisco, CA (37.7749°N, 122.4194°W)');
console.log('To:    Boston, MA 02118  (42.3396°N, 71.0693°W)');
console.log('');
console.log('Great-circle (straight-line) distance:');
console.log('  ' + (R_km * c).toFixed(1) + ' km');
console.log('  ' + (R_mi * c).toFixed(1) + ' miles');
"
